unit RefAliasDemo;

interface

uses Classes;

type
  IThing = interface
    ['{8E5C2C1A-FBB7-4DD0-9B7A-CFBE5F58D7B0}']
    procedure DoStuff;
  end;

  TThing = class(TInterfacedObject, IThing)
    procedure DoStuff;
  end;

procedure LeakOrCrash;

implementation

procedure TThing.DoStuff; begin end;

procedure LeakOrCrash;
var
  Obj : TThing;
  Itf : IThing;
begin
  Obj := TThing.Create;     // refcount = 0
  Itf := Obj;                // refcount = 1
  Obj.DoStuff;               // legal -- TObject reference
  Obj.Free;                   // refcount still 1 -> dangling Itf
  Itf := nil;                 // refcount 1 -> 0 -> double-free.
end;

end.
